}

#version 120

varying vec2 texcoord;

uniform sampler2D gcolor;
uniform float viewWidth;

// Simple Bloom extraction and horizontal blur
void main() {
    vec3 color = texture2D(gcolor, texcoord).rgb;

    // Brightness extraction
    float brightness = dot(color, vec3(0.2126, 0.7152, 0.0722));
    vec3 brightColor = (brightness > 1.0) ? color : vec3(0.0);

    // Horizontal Blur
    vec3 result = brightColor * 0.227027;
    float offset = 1.0 / viewWidth;
    result += texture2D(gcolor, texcoord + vec2(offset * 1.384615, 0.0)).rgb * 0.316216;
    result += texture2D(gcolor, texcoord + vec2(offset * 3.230769, 0.0)).rgb * 0.070270;
    result += texture2D(gcolor, texcoord - vec2(offset * 1.384615, 0.0)).rgb * 0.316216;
    result += texture2D(gcolor, texcoord - vec2(offset * 3.230769, 0.0)).rgb * 0.070270;

    gl_FragColor = vec4(result, 1.0);
}

#version 120

varying vec2 texcoord;

uniform sampler2D gcolor; // Original color from composite
uniform sampler2D composite1; // Horizontally blurred bright pass
uniform float viewHeight;

// Vertical blur and combine
void main() {
    vec3 originalColor = texture2D(gcolor, texcoord).rgb;
    vec3 blurColor = texture2D(composite1, texcoord).rgb * 0.227027;

    float offset = 1.0 / viewHeight;
    blurColor += texture2D(composite1, texcoord + vec2(0.0, offset * 1.384615)).rgb * 0.316216;
    blurColor += texture2D(composite1, texcoord + vec2(0.0, offset * 3.230769)).rgb * 0.070270;
    blurColor += texture2D(composite1, texcoord - vec2(0.0, offset * 1.384615)).rgb * 0.316216;
    blurColor += texture2D(composite1, texcoord - vec2(0.0, offset * 3.230769)).rgb * 0.070270;

    // Combine
    vec3 result = originalColor + blurColor * 0.5; // Bloom strength 0.5

    gl_FragColor = vec4(result, 1.0);
}

