// Shadow sampling function with PCF (Soft Shadows)
float getShadow(vec3 pos) {
    vec4 shadowPos = shadowProjection * shadowModelView * vec4(pos, 1.0);
    shadowPos.xyz = shadowPos.xyz * 0.5 + 0.5; // Convert to [0, 1] range

    if (shadowPos.x < 0.0 || shadowPos.x > 1.0 || shadowPos.y < 0.0 || shadowPos.y > 1.0) return 1.0;

    float shadowResult = 0.0;
    float bias = 0.005;

    // PCF 3x3
    for (int x = -1; x <= 1; ++x) {
        for (int y = -1; y <= 1; ++y) {
            float depth = texture2D(shadow, shadowPos.xy + vec2(x, y) * 0.001).r;
            shadowResult += (shadowPos.z - bias > depth) ? 0.5 : 1.0;
        }
    }

    return shadowResult / 9.0;
}

