uniform float wetness;
uniform float viewWidth;
uniform float viewHeight;

// Simple SSAO implementation
float calculateSSAO(vec2 coord, float depth, vec3 normal) {
    float ao = 0.0;
    float radius = 0.01; // Screen space radius
    int samples = 8;

    for(int i = 0; i < samples; i++) {
        // Simple pseudo-random sampling
        vec2 offset = vec2(sin(float(i) * 12.9898), cos(float(i) * 78.233)) * radius;
        float sampleDepth = texture2D(depthtex0, coord + offset).r;

        if(sampleDepth < depth) {
             ao += 1.0;
        }
    }

    return 1.0 - (ao / float(samples)) * 0.5; // Strength adjustment
}
